// lib/quiz.ts
/**
 * Generate a simple 6‑question quiz for a given day.
 * Each question asks the meaning of a term (Vietnamese) and provides
 * 4 options (English terms). The correct answer is the original term.
 *
 * The function reads `data/words.json` (generated by the previous step)
 * and returns an array of quiz items.
 */
import path from "path";
import fs from "fs";

type QuizItem = {
  question: string; // Vietnamese meaning
  options: string[]; // English terms (shuffled)
  answer: string; // correct English term
  explanation: string; // example sentence (English)
};

/** Shuffle an array – Fisher‑Yates */
function shuffle<T>(arr: T[]): T[] {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

export async function getQuizForDay(day: number): Promise<QuizItem[]> {
  const wordsPath = path.resolve("data", "words.json");
  if (!fs.existsSync(wordsPath)) {
    throw new Error("words.json not found – run the token generation step first");
  }
  const raw = await fs.promises.readFile(wordsPath, "utf8");
  const data = JSON.parse(raw);
  const dayWords = data.words.filter((w: any) => w.day === day);
  if (dayWords.length === 0) {
    throw new Error(`No words found for day ${day}`);
  }
  // pick first 6 (or all if less)
  const selected = dayWords.slice(0, 6);
  const allTerms = dayWords.map((w: any) => w.term);
  const quiz: QuizItem[] = selected.map((w: any) => {
    const wrong = shuffle(allTerms.filter((t) => t !== w.term)).slice(0, 3);
    const options = shuffle([w.term, ...wrong]);
    return {
      question: w.meaning_vi,
      options,
      answer: w.term,
      explanation: w.example_en,
    } as QuizItem;
  });
  return quiz;
}
